begin;select plan(12);
select ok(to_regclass('public.public_player_profiles')is not null,'safe profiles exist');select ok(to_regclass('public.public_player_statistics')is not null,'safe statistics exist');select ok(to_regclass('public.public_match_history')is not null,'safe history exists');select ok(has_table_privilege('anon','public.public_player_profiles','SELECT'),'anonymous profile access');select ok(has_table_privilege('anon','public.public_match_history','SELECT'),'anonymous history access');select ok(not has_table_privilege('anon','public.accounts','SELECT'),'contacts denied');select ok(not has_table_privilege('anon','public.club_memberships','SELECT'),'memberships denied');select ok(not has_table_privilege('anon','public.event_attendance','SELECT'),'attendance denied');select ok(not exists(select 1 from information_schema.columns where table_name='public_player_profiles'and column_name ilike'%email%'),'email absent');select ok(exists(select 1 from pg_indexes where indexname='match_participants_player_match_idx'),'history pagination indexed');select ok(exists(select 1 from information_schema.columns where table_name='public_match_history'and column_name='record_class'),'rank filter exposed');select ok(exists(select 1 from information_schema.columns where table_name='public_match_history'and column_name='has_revision_history'),'correction state exposed');select*from finish();rollback;
